      try { candidate = root && typeof root.get === 'function' ? (root.get('conversation') || root.get('uiConversation')) : null; } catch (e) {}
      if (!candidate) {
        try { candidate = root && (root.conversation || root.uiConversation) || null; } catch (e) {}
      }
