      '.dsh-canvas-overlay{position:fixed;top:0;right:0;bottom:0;z-index:1000;display:flex;flex-direction:column;isolation:isolate;overflow:hidden;container-type:inline-size;background:#15171c;border-left:1px solid rgba(255,255,255,.1);box-shadow:-14px 0 34px rgba(0,0,0,.28);color:#e5e7eb;pointer-events:auto}',
